import json
import re
import requests
from threading import Thread
from auto_config.generator.utils.utils import sorting_key


class WFTException(Exception):
    pass


class ThreadWithReturnValue(Thread):

    def __init__(
        self, group=None, target=None, name=None, args=(), kwargs={}, Verbose=None
    ):
        Thread.__init__(self, group, target, name, args, kwargs)
        self._return = None

    def run(self):
        if self._target is not None:
            self._return = self._target(*self._args, **self._kwargs)

    def join(self, *args):
        Thread.join(self, *args)
        return self._return


class BuildFetcher:

    BUILD_REGEX = re.compile(r"SBTS(?:00|\d\d(?:R\d|SP|A|B))_ENB_\S+")
    PROJECT = "SBTS"
    COMPONENT = "CI_ENB"
    WFT_IHT_REQUEST_BODY = json.dumps(
        {
            "page": "",
            "items": "50",
            "sorting_field": "created_at",
            "sorting_direction": "DESC",
            "group_by": "",
            "group_by_processor": "",
            "columns": {
                "0": {"id": "version"},
                "1": {"id": "component"},
                "2": {"id": "state"},
            },
            "projects": [""],
            "view_filters_attributes": {
                #           "0": {"column": "state", "operation": "eq", "value": "released", "parameter": ""},
                "0": {
                    "column": "state",
                    "operation": "eq",
                    "value": "",
                    "parameter": "",
                },
                "1": {
                    "column": "component",
                    "operation": "eq",
                    "value": COMPONENT,
                    "parameter": "",
                },
            },
            "access_key": "kpJnlSJDyP2cE2MxYa49jvmR2upSTFNn2JhaIUeC",
        }
    )
    WFT_HEADERS = {"Accept": "application/json", "Content-Type": "application/json"}
    WFT_API_URL = f"https://wft.int.net.nokia.com:8091/{PROJECT}/api/v1/build.json"

    def get_builds(self):
        latest_builds = []
        items = 50
        try:
            while len(latest_builds) < items:
                for version, _ in self._get_latest_builds():
                    if re.match(BuildFetcher.BUILD_REGEX, version):
                        latest_builds.append(version)
            return_value = sorted(latest_builds[:50], key=sorting_key)
        except Exception:
            return_value = []

        return return_value

    def _get_latest_builds(self):
        versions = []
        with requests.Session() as session:
            result = session.get(
                url=BuildFetcher.WFT_API_URL,
                data=BuildFetcher.WFT_IHT_REQUEST_BODY,
                headers=BuildFetcher.WFT_HEADERS,
            )

        if result.ok:
            json_result = result.json()
            for item in json_result["items"]:
                state = item["state"]
                version = item["version"]
                if (
                    state == "ERROR"
                    or state == "NOT_RELEASED"
                    or state == "CANCELED"
                    or state == "SKIPPED"
                    or state == "BUILDING"
                    or state == "BUILDABLE"
                    or state == "SUCCEEDED"
                    or state == "FROZEN"
                ):
                    continue
                versions.append((version, state))
        else:
            raise WFTException("No builds available")
        return versions


if __name__ == "__main__":
    builds = BuildFetcher().get_builds()[:50]
    print(builds)
